const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
if (!reduced) document.body.classList.add('js-motion');
const reveals = new IntersectionObserver(entries => entries.forEach(e => { if(e.isIntersecting){e.target.classList.add('visible');reveals.unobserve(e.target);} }), {threshold:.08});
document.querySelectorAll('.reveal').forEach(el => reveals.observe(el));
const progress = document.querySelector('.scroll-progress');
const hand = document.querySelector('.hand-image');
let queued=false;
function scrollUpdate(){queued=false;const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=`${max>0?scrollY/max*100:0}%`;if(!reduced&&innerWidth>760)hand.style.transform=`translateY(${Math.min(scrollY*.13,100)}px) rotate(${Math.min(scrollY*.009,7)}deg)`;}
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(scrollUpdate);}},{passive:true});scrollUpdate();
const menu = document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close menu':'Open menu');document.querySelector('.nav nav').classList.toggle('open',open);});
document.querySelectorAll('.nav nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');document.querySelector('.nav nav').classList.remove('open');}));
const projectData={hand:{label:'Upper limb / Design concept',title:'Tomorrow’s Touch',copy:'A concept study in prosthetic hand design, exploring the connection between industrial form and human experience. Carbon surfaces, metal joints and finger proportions shape its visual language. The render and 3D model illustrate a design idea; they are not a clinical prototype or an approved medical product.',tags:['Form and ergonomics','Materials','3D modeling']},joint:{label:'Mechanism / Design study',title:'Geometry of Motion',copy:'An exploration of rotation axes, range of motion and structural clarity. This study treats the mechanism as part of a product’s visual identity. Explore the technical structure and finger movement in the interactive 3D view.',tags:['Joints and connections','Motion study','Mechanism design']}};
const dialog=document.querySelector('#project-dialog');
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const data=projectData[button.dataset.project];document.querySelector('#dialog-label').textContent=data.label;document.querySelector('#dialog-title').textContent=data.title;document.querySelector('#dialog-copy').textContent=data.copy;document.querySelector('#dialog-tags').replaceChildren(...data.tags.map(t=>{const s=document.createElement('span');s.textContent=t;return s;}));dialog.showModal();}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
document.querySelector('#dialog-explore').addEventListener('click',()=>dialog.close());
document.querySelector('#contact-button').addEventListener('click',()=>document.querySelector('#contact-dialog').showModal());
function downloadResume(){const content=`<!doctype html><html lang="en" dir="ltr"><meta charset="utf-8"><title>Erfan Mohiti | Professional profile</title><style>body{font-family:Tahoma,sans-serif;max-width:750px;margin:70px auto;padding:30px;line-height:2;color:#18352d}h1{font-size:36px}small{color:#677f75}@media print{body{margin:0}}</style><h1>Erfan Mohiti</h1><p>Medical prosthesis designer</p><hr><h2>Design approach</h2><p>Design at the intersection of engineering, ergonomics and human experience, with a focus on form, movement and everyday independence.</p><h2>Areas of focus</h2><p>Industrial design · CAD modeling · Ergonomics · Prototyping</p><h2>Portfolio</h2><p>Tomorrow’s Touch — Prosthetic hand concept<br>Geometry of Motion — Form and mechanism study</p><small>This introduction does not include verified educational or professional history. It will be completed when the original CV is supplied. The projects are illustrative concepts.</small></html>`;const url=URL.createObjectURL(new Blob([content],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Erfan-Mohiti-Profile.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
document.querySelector('#download-resume').addEventListener('click',downloadResume);document.querySelector('#contact-resume').addEventListener('click',downloadResume);
document.querySelector('#year').textContent=new Date().getFullYear();
const viewer=document.querySelector('#viewer');let viewerStarted=false;
const viewerObserver=new IntersectionObserver(async entries=>{if(entries.some(e=>e.isIntersecting)&&!viewerStarted){viewerStarted=true;viewerObserver.disconnect();try{const {initViewer}=await import('./viewer.js');await initViewer(viewer,reduced);}catch(error){document.querySelector('#viewer-status').textContent='The 3D view is unavailable in this browser. See the concept render in Selected work.';console.warn('3D viewer unavailable',error);}}},{rootMargin:'180px'});viewerObserver.observe(viewer);
